#include <stdio.h>

void swap(int *x, int *y) {
    int temp = *x;
    *x = *y;
    *y = temp;
}

void order(int *x, int *y) {
    if (*x > *y) {
        swap(x, y);
    }
}

int main() {
    int a = 30, b = 10, c = 20;
    order(&a, &b);
    order(&b, &c);
    order(&a, &b);
    printf("%d %d %d\n", a, b, c);
    return 0;
}
